from dataclasses import FrozenInstanceError

import pytest

from chatreq import ChatRequest


def base():
    return ChatRequest.builder().model("small-1").system("Be terse.").user("Hi")


def test_happy_path_and_payload() -> None:
    request = base().max_tokens(64).build()
    assert request.messages == (("system", "Be terse."), ("user", "Hi"))
    assert request.to_payload()["messages"][1] == {"role": "user", "content": "Hi"}


def test_payload_is_a_fresh_copy() -> None:
    request = base().build()
    payload = request.to_payload()
    payload["messages"].clear()
    assert len(request.to_payload()["messages"]) == 2


def test_required_fields() -> None:
    with pytest.raises(ValueError, match="model"):
        ChatRequest.builder().user("Hi").build()
    with pytest.raises(ValueError, match="user message"):
        ChatRequest.builder().model("m").system("x").build()


def test_system_message_rules() -> None:
    with pytest.raises(ValueError, match="first"):
        ChatRequest.builder().model("m").user("Hi").system("late").build()
    with pytest.raises(ValueError, match="only one"):
        ChatRequest.builder().model("m").system("a").system("b").user("Hi").build()


def test_temperature_range() -> None:
    with pytest.raises(ValueError, match="temperature"):
        base().temperature(3.0).build()


def test_budget_is_checked_after_all_values_are_known() -> None:
    long_text = "x" * 4000                      # about 1000 tokens
    builder = ChatRequest.builder(context_window=1200).model("m").max_tokens(500)
    builder.user(long_text)                      # max_tokens was set BEFORE the messages
    with pytest.raises(ValueError, match="context window"):
        builder.build()
    assert builder.max_tokens(100).build().max_tokens == 100


def test_two_builds_are_independent_and_immutable() -> None:
    builder = base()
    first = builder.build()
    builder.user("second turn")
    second = builder.build()
    assert len(first.messages) == 2 and len(second.messages) == 3
    with pytest.raises(FrozenInstanceError):
        first.model = "other"


def test_to_builder_copies_and_changes_one_field() -> None:
    original = base().max_tokens(64).build()
    retry = original.to_builder().max_tokens(128).build()
    assert (original.max_tokens, retry.max_tokens) == (64, 128)
    assert retry.messages == original.messages
